import numpy as np

def problem(x: np.ndarray) -> float:
    if x.shape != (3,):
        raise ValueError("Input must be a 3D NumPy array.")

    quadratic_term = x[0]**2 + 0.5 * x[1]**2 + 0.3 * x[2]**2
    sine_term = 0.5 * np.sin(2 * x[0])
    tanh_term = 0.3 * np.tanh(3*x[1])
    result = quadratic_term + sine_term + tanh_term
    return float(result)
